    if (ui) {
      analysisList.push({ range: ui.range, count: ui.scenes.length, uploaded: ui.uploaded });
      onStep({ kind: 'analysis', phase: 'done', count: ui.scenes.length, uploaded: ui.uploaded, range: ui.range, scenes: ui.scenes.slice(0, 40) });
    }
