    message: finalText,
    segments: r.segments,
    changed: r.changed,
    exportSettings: r.exportSettings,
    exportChanged: r.exportChanged,
    actions: r.actions,
    uiActions: r.uiActions,
    found: foundList,
    analysis: analysisList,
    totalSeconds: r.currentTotal,
    usage,
    iterations: iterations + 1,
